SELECT CASE WHEN discount_pct >= 0.36 THEN 'LARGE' ELSE 'SMALL' END AS discount_pct_tier, ROUND(SUM(discount_pct) / NULLIF(COUNT(CASE WHEN promo_code = 'WELCOME5' THEN 1 END), 0), 2) AS discount_pct_per_welcome5, APPROX_PERCENTILE(discount_pct, 0.5) AS discount_pct_p50, SIZE(COLLECT_SET(promo_code)) AS num_promo_codes FROM promotions GROUP BY CASE WHEN discount_pct >= 0.36 THEN 'LARGE' ELSE 'SMALL' END HAVING ROUND(SUM(discount_pct) / NULLIF(COUNT(CASE WHEN promo_code = 'WELCOME5' THEN 1 END), 0), 2) < 1000000
